# Installs {{ app }} {{ version }} from {{ repository_url }}.
# Generated by ag-release {{ ag_release_version }}.
class {{ class_name }} < Formula
{%- if let Some(description) = description %}
  desc {{ description }}
{%- endif %}
  homepage {{ homepage }}
  version {{ formula_version }}
{%- if let Some(license) = license %}
  license {{ license }}
{%- endif %}
{%- for platform in platforms %}

  on_{{ platform.name }} do
{%- for archive in platform.archives %}
    on_{{ archive.arch }} do
      url {{ archive.url }}
      sha256 {{ archive.sha256 }}
    end
{%- endfor %}
  end
{%- endfor %}

  def install
    bin.install {{ binaries }}
  end

  test do
{%- for binary in binary_names %}
    system bin/{{ binary }}, "--version"
{%- endfor %}
  end
end
